# Generated by build.py from recipe.yml for recipe ftp-copy-a-report-from-ftp-to-s3. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1,DNS:*.s3.us-east-1.amazonaws.com"'
$server0 = Start-Process surl -ArgumentList '--directory', 'ftp-site', '--cert', 'server.pem', '--key', 'server.key', '--user', 'nightly:s3cret', 'ftp://127.0.0.1:8080/' -PassThru -NoNewWindow
$server1 = Start-Process surl -ArgumentList '--directory', 'store', '--cert', 'server.pem', '--key', 'server.key', '--user', 'AKIAIOSFODNN7EXAMPLE:s3cret', '--allow-uploads', 's3://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --fail-early -sS --ssl-reqd --cacert server.pem -u nightly:s3cret -o report.csv ftp://127.0.0.1:8080/out/report.csv --next --cacert server.pem --connect-to ::127.0.0.1:8081 -u AKIAIOSFODNN7EXAMPLE:s3cret -T report.csv s3://reports/2026-11-20.csv } finally { Stop-Process $server0; Stop-Process $server1 }
